<?php
declare(strict_types=1);
require_once __DIR__ . '/../../src/bootstrap.php';
require_once __DIR__ . '/../../templates/layout.php';
$externalId=(string)($_GET['patient_external_id']??'PAT-1007'); $source=(string)($_GET['source_system']??'HIS-DEMO');
$patient=current(array_filter($repo->all('patients'),fn($p)=>$p['external_id']===$externalId && ($p['source_system']??'')===$source)) ?: null;
$orders=$patient?array_values(array_filter($repo->all('diet_orders'),fn($o)=>(int)$o['patient_id']===(int)$patient['id'] && ($o['status']??'')==='active')):[];
$diets=$repo->all('diet_types'); $clinicians=$repo->all('clinicians');
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf($_POST['csrf_token']??null); $diet=current(array_filter($diets,fn($d)=>(int)$d['id']===(int)$_POST['diet_type_id'])) ?: null; $clinician=current(array_filter($clinicians,fn($c)=>(int)$c['id']===(int)$_POST['clinician_id'])) ?: null; if($patient&&$diet&&$clinician){$order=$repo->insert('diet_orders',['patient_id'=>$patient['id'],'patient_name'=>$patient['name'],'diet_code'=>$diet['code'],'diet_name'=>$diet['name'],'clinician_name'=>$clinician['name'],'effective_from'=>$_POST['effective_from'],'meal_texture'=>$_POST['meal_texture'],'calories'=>(int)$_POST['calories'],'notes'=>trim($_POST['notes']),'status'=>'active']); echo '<script>window.parent.postMessage('.json_encode(['type'=>'kitchenflow:diet-order-created','order_id'=>$order['id'],'patient_external_id'=>$externalId]).',"*");</script>'; $orders[]=$order; $success='Diet order sent to KitchenFlow.'; }} ?>
