"widget-section"><div class="widget-section-head"><div><h2>Prescribe / update diet</h2><p>Order changes are sent to the kitchen service queue.</p></div></div><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="row g-2"><div class="col-md-6"><label class="form-label">Diet protocol</label><select name="diet_type_id" class="form-select" required><?php foreach($diets as $d): ?><option value="<?= $d['id'] ?>"><?= e($d['code'].' — '.$d['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Prescriber</label><select name="clinician_id" class="form-select" required><?php foreach($clinicians as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name'].' · '.$c['specialty']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Effective date</label><input type="date" name="effective_from" value="<?= date('Y-m-d') ?>" class="form-control" required></div><div class="col-md-4"><label class="form-label">Texture</label><select name="meal_texture" class="form-select"><option>Regular</option><option>Soft</option><option>Pureed</option><option>Thickened liquids</option></select></div><div class="col-md-4"><label class="form-label">Calories / day</label><input type="number" name="calories" value="1800" class="form-control"></div><div class="col-12"><label class="form-label">Clinical instructions</label><input name="notes" class="form-control" placeholder="Restrictions, fluid limit, cultural preference, etc."></div></div><button class="btn btn-primary mt-3"><i class="bi bi-send me-2"></i>Send to kitchen service</button></form></div><?php endif; ?></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
